sp_executesql.examples.input-params.sql:
DECLARE @minLoans int = 3;
EXEC sp_executesql
    N'SELECT ReaderId, ReaderName FROM (VALUES (1, N''Amy'', 5), (2, N''Ben'', 1)) AS r(ReaderId, ReaderName, LoanCount) WHERE LoanCount >= @minLoans',
    N'@minLoans int',
    @minLoans;
-- Result: only Amy (LoanCount = 5 >= 3); @stmt and @params must be nvarchar (N'...'), not a plain string

sp_executesql.examples.output-and-trap.sql:
DECLARE @readerName nvarchar(50);
EXEC sp_executesql
    N'SELECT @name = ReaderName FROM (VALUES (1, N''Amy''), (2, N''Ben'')) AS r(ReaderId, ReaderName) WHERE ReaderId = @id',
    N'@id int, @name nvarchar(50) OUTPUT',
    @id = 2,
    @name = @readerName OUTPUT;
SELECT @readerName;   -- Result: Ben
SET @readerName = NULL;
EXEC sp_executesql
    N'SELECT @name = ReaderName FROM (VALUES (1, N''Amy''), (2, N''Ben'')) AS r(ReaderId, ReaderName) WHERE ReaderId = @id',
    N'@id int, @name nvarchar(50) OUTPUT',
    @id = 2,
    @name = @readerName;
SELECT @readerName;   -- Result: NULL -- the caller forgot OUTPUT this time, so the value never comes back

sp_executesql.examples.insert-exec.sql:
CREATE TABLE #t (ReaderId int, ReaderName nvarchar(50));
INSERT INTO #t
EXEC sp_executesql
    N'SELECT ReaderId, ReaderName FROM (VALUES (1, N''Amy''), (2, N''Ben'')) AS r(ReaderId, ReaderName) WHERE ReaderId > @minId',
    N'@minId int',
    @minId = 1;
SELECT * FROM #t;   -- Result: only one row (2, 'Ben')
DROP TABLE #t;

sp_executesql.examples.dynamic-table.sql:
CREATE TABLE #Cat_BookCopy (CopyNo int, Branch nvarchar(20));
INSERT INTO #Cat_BookCopy VALUES (1, N'Main'), (2, N'East'), (3, N'Main');
DECLARE @tableName sysname = N'#Cat_BookCopy';
DECLARE @paramDef nvarchar(max) = N'@branch nvarchar(20)';
DECLARE @sql nvarchar(max) = N'SELECT COUNT(*) AS Cnt FROM ' + QUOTENAME(@tableName) + N' WHERE Branch = @branch';
EXEC sp_executesql @sql, @paramDef, @branch = N'Main';
-- Result: Cnt = 2; the table name can only be concatenated with QUOTENAME (blocks injection, can't be parameterized) --
-- the filter value is parameterized instead: concatenating raw input into SQL is an injection hole, and gives each value its own cached plan
DROP TABLE #Cat_BookCopy;

