sp_getapplock.examples.transaction-owner.sql:
BEGIN TRANSACTION;
DECLARE @result int;
EXEC @result = sp_getapplock @Resource = N'Loan:CopyNo:1', @LockMode = N'Exclusive';
SELECT @result;   -- Result: 0 (granted immediately, no wait)
COMMIT TRANSACTION;   -- the transaction ends, the lock releases automatically (@LockOwner defaults to 'Transaction')

sp_getapplock.examples.session-owner.sql:
DECLARE @result int;
EXEC @result = sp_getapplock @Resource = N'Loan:CopyNo:2', @LockMode = N'Exclusive', @LockOwner = N'Session';
SELECT @result;   -- Result: 0
EXEC sp_releaseapplock @Resource = N'Loan:CopyNo:2', @LockOwner = N'Session';
-- @LockOwner = 'Session' has to be released yourself; it won't release automatically when the transaction ends

sp_getapplock.examples.no-transaction-trap.sql:
DECLARE @result int;
EXEC @result = sp_getapplock @Resource = N'Loan:CopyNo:3', @LockMode = N'Exclusive';
-- Result: the call fails (8351: must run inside a transaction, since @LockOwner defaults to 'Transaction')
-- either wrap it in BEGIN TRANSACTION, or pass @LockOwner = 'Session'

sp_releaseapplock.examples.session-release.sql:
DECLARE @result int;
EXEC sp_getapplock @Resource = N'Loan:CopyNo:4', @LockMode = N'Exclusive', @LockOwner = N'Session';
EXEC @result = sp_releaseapplock @Resource = N'Loan:CopyNo:4', @LockOwner = N'Session';
SELECT @result;   -- Result: 0 (released successfully)

sp_releaseapplock.examples.early-release.sql:
BEGIN TRANSACTION;
EXEC sp_getapplock @Resource = N'Loan:CopyNo:5', @LockMode = N'Exclusive';
EXEC sp_releaseapplock @Resource = N'Loan:CopyNo:5';
-- the transaction hasn't committed yet, but the lock was already released manually; @LockOwner defaulting to 'Transaction' can still be released early, without waiting for the transaction to end
COMMIT TRANSACTION;

sp_releaseapplock.examples.not-held-trap.sql:
DECLARE @result int;
EXEC @result = sp_releaseapplock @Resource = N'Loan:CopyNo:999', @LockOwner = N'Session';
SELECT @result;
-- Result: -999 -- this session doesn't hold that lock (the name never matched any sp_getapplock call);
-- @Resource/@LockOwner must match the original acquire call exactly to release it

