sp_refreshview.examples.select-star.sql:
CREATE TABLE dbo.Lib_Tag (TagId int, TagName nvarchar(30));
GO
CREATE VIEW dbo.Lib_TagView AS SELECT * FROM dbo.Lib_Tag;
GO
ALTER TABLE dbo.Lib_Tag ADD TagColor nvarchar(10) NULL;
SELECT * FROM dbo.Lib_TagView;
-- Result: still only TagId and TagName -- a SELECT * view freezes its column list at creation time
EXEC sp_refreshview N'dbo.Lib_TagView';
SELECT * FROM dbo.Lib_TagView;   -- Result: three columns now, TagColor shows up too
DROP VIEW dbo.Lib_TagView;
DROP TABLE dbo.Lib_Tag;

